259	/** Return with sinus of an angle in 0.1 degree
260	 *
261	 * @param angle in 0.1 degree
262	 * @return sinus of 'angle'. sin(-900) = -32767, sin(900) = 32767
263	 */
264	void EPIC_TrigoSinCosP1(int16_t angle, int16_t *sin_val, int16_t *cos_val)
265	{
266	    while (angle < 0) angle += 3600;
267	    while (angle >= 3600) angle -= 3600;
268	
269	    int32_t angle_low = angle / 10;
270	    int32_t angle_hight = angle_low + 1;
271	    int32_t angle_rem = angle  - (angle_low * 10);
272	
273	    if (sin_val)
274	    {
275	        int32_t s1 = EPIC_TrigoSin(angle_low);
276	        int32_t s2 = EPIC_TrigoSin(angle_hight);
277	
278	        *sin_val = (s1 * (10 - angle_rem) + s2 * angle_rem) / 10;
279	    }
280	    if (cos_val)
281	    {
282	        int32_t c1 = EPIC_TrigoSin(angle_low + 90);
283	        int32_t c2 = EPIC_TrigoSin(angle_hight + 90);
284	
285	        *cos_val = (c1 * (10 - angle_rem) + c2 * angle_rem) / 10;
286	    }
287	}
