307	    x0 = HAL_MAX(layer0->x_offset, layer1->x_offset);
308	    y0 = HAL_MAX(layer0->y_offset, layer1->y_offset);
309	    x1 = HAL_MIN(layer0->x_offset + layer0->width - 1, layer1->x_offset + layer1->width - 1);
