315	        res_area->y0 = y0;
316	        res_area->x1 = x1;
317	        res_area->y1 = y1;
318	    }
319	
320	    if ((x0 <= x1) && (y0 <= y1))
321	    {
322	        return true;
323	    }
324	    else
325	    {
326	        return false;
327	    }
