117	/* EPIC 等待超时 ⇒ 本次当作**失败**返回：上层 vmap_blit 的 CPU 兜底会把这一块
118	 * 重做一遍，所以既不会卡死、也不会在半搬完的画布上留错像素（用户 2026-09-26）。 */
119	extern volatile uint32_t g_epic_wait_timeouts;
120	
121	static bool epic_result(uint32_t wt_before, bool hal_ok, const char * what)
122	{
123	  if (g_epic_wait_timeouts != wt_before)
124	    {
125	      syslog(LOG_WARNING,
126	             "[vblit] EPIC 等待超时（%s；累计 %u 次）⇒ 本次退回 CPU 重做\n",
127	             what, (unsigned)g_epic_wait_timeouts);
128	      return false;
129	    }
130	
131	  return hal_ok;
132	}
