151	    }
152	
153	  /* 坐标/尺寸寄存器是 16 位，且上层另有溢出检查（EPIC_COORDINATES_MAX）。 */
154	  if (sx + w > EPIC_COORDINATES_MAX || sy + h > EPIC_COORDINATES_MAX
155	      || dx + w > EPIC_COORDINATES_MAX || dy + h > EPIC_COORDINATES_MAX)
156	    {
157	      return false;
158	    }
159	
160	  /*
161	   * ⚠ 这里的摆法是**踩过坑**的，改动前先看这段：
162	   *
163	   * EPIC 的混合语义是"**图层内容留在它自己的画布位置**"：对画布点 (X,Y)，
164	   * 它读 `in.data[X - in.x_offset]` 写到 `out.data[X - out.x_offset]`
165	   * （见 `EPIC_ConfigOutputLayer()` 里 `offset = (y0 - output->y_offset) *
166	   * output->total_width + (x0 - output->x_offset)` 那一段）。
167	   * 也就是说：**平移必须体现在 data 指针上，不能体现在 x_offset/y_offset 上**
168	   * —— 后者会让内容停在原地（那就成了"原地混合"，不是搬运）。
169	   * 实测（2026-09-25 开机自检）：把位移放进 offset 时，九个方向**全部**与 CPU
170	   * 不一致（EPIC 只在两个矩形的交集里写，落点还差了一个位移）。
171	   *
172	   * 所以：
173	   *   - 两个 `data` 各自指向自己矩形的左上角像素（位移在这里）；
174	   *   - 两个 `x_offset/y_offset` **取同一个值**（用目的矩形的坐标），
175	   *     这样图层矩形与输出矩形完全重合 ⇒ 交集 = 整个矩形，
176	   *     EPIC 才会对每一列都读一次源；否则不重合的那部分会被 `continue` 掉
177	   *     （`EPIC_ConfigBlendEx()` 里"输入与输出不相交就跳过该层"）。
178	   *   - `total_width` = 各自的行跨度（像素），矩形尺寸另给。
179	   *   - 单输入层 + 不透明 alpha（`LayerConfigInit` 置 255）⇒ 逐位拷贝。
180	   */
181	  HAL_EPIC_LayerConfigInit(&in);
182	  in.data = epic_at((void *)src_buf, src_stride, sx, sy);
183	  in.color_mode = EPIC_COLOR_RGB565;
184	  in.width = (uint16_t)w;
185	  in.height = (uint16_t)h;
186	  in.x_offset = (int16_t)dx;
187	  in.y_offset = (int16_t)dy;
188	  in.total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
189	
190	  HAL_EPIC_LayerConfigInit(&out);
191	  out.data = epic_at((void *)dst_buf, dst_stride, dx, dy);
192	  out.color_mode = EPIC_COLOR_RGB565;
193	  out.width = (uint16_t)w;
194	  out.height = (uint16_t)h;
195	  out.x_offset = (int16_t)dx;
196	  out.y_offset = (int16_t)dy;
197	  out.total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
198	
199	  bool ok = epic_result(wt_before, (lv_epic_blend(&in, 1, &out)) == HAL_OK, "copy");
200	
201	  if (ok)
202	    {
203	      /* 目的侧作废（见 epic_invalidate_rect_rows 的说明）；out.data 就是矩形左上角
204	       * —— 这条摆放约定在 2026-09-25 的开机自检里钉过（见上面那段 ⚠ 注释）。 */
205	      epic_invalidate_rect_rows(out.data, dst_stride, w, h);
206	    }
207	
208	  return ok;
209	}
