211	bool myvendor_epic_fill(uint16_t * dst_buf, uint32_t dst_stride, int32_t x,
212	  int32_t y, int32_t w, int32_t h, uint16_t color565)
213	{
214	  const uint32_t wt_before = g_epic_wait_timeouts;
215	  EPIC_LayerConfigTypeDef out;
216	
217	  if (lv_epic_get_handle() == NULL)
218	    {
219	      return false;
220	    }
221	
222	  if (x < 0 || y < 0)
223	    {
224	      return false;
225	    }
226	
227	  if (x + w > EPIC_COORDINATES_MAX || y + h > EPIC_COORDINATES_MAX)
228	    {
229	      return false;
230	    }
231	
232	  HAL_EPIC_LayerConfigInit(&out);
233	  out.data = epic_at((void *)dst_buf, dst_stride, x, y);
234	  out.color_mode = EPIC_COLOR_RGB565;
235	  out.width = (uint16_t)w;
236	  out.height = (uint16_t)h;
237	  out.x_offset = (int16_t)x;
238	  out.y_offset = (int16_t)y;
239	  out.total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
240	  out.color_en = true;
241	  out.color_r = epic_expand5((uint16_t)((color565 >> 11) & 0x1fu));
242	  out.color_g = epic_expand6((uint16_t)((color565 >> 5) & 0x3fu));
243	  out.color_b = epic_expand5((uint16_t)(color565 & 0x1fu));
244	
245	  /* 输入层数 = 0 ⇒ `lv_epic_fill()` 走 HAL_EPIC_fill(NULL, 0, &out) == HAL_OK; 这条路径 */
246	  bool ok = epic_result(wt_before, (lv_epic_fill(NULL, 0, &out)) == HAL_OK, "fill");
247	
248	  if (ok)
249	    {
250	      epic_invalidate_rect_rows(out.data, dst_stride, w, h);
251	    }
252	
253	  return ok;
254	}
