356	static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
357	  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
358	  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
359	  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy)
360	{
361	  EPIC_LayerConfigTypeDef layers[2];
362	  EPIC_LayerConfigTypeDef out;
363	  bool ok;
364	
365	  if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
366	      || angle10 < 0 || angle10 >= 3600)
367	    {
368	      return false;
369	    }
370	
371	  /* 坐标寄存器 10 bit（EPIC_COORDINATES_MAX = 1010），越界 HAL 会断言。 */
372	  if (src_w > EPIC_COORDINATES_MAX || src_h > EPIC_COORDINATES_MAX
373	      || dst_w > EPIC_COORDINATES_MAX || dst_h > EPIC_COORDINATES_MAX)
374	    {
375	      return false;
376	    }
377	
378	  /* EPIC 绕过 CPU 缓存直读 PSRAM：先把源写回去。 */
379	  lv_epic_clean_invalidate_cache_range(src_buf,
380	    (size_t)src_stride * (size_t)src_h);
381	
382	  HAL_EPIC_LayerConfigInit(&layers[0]);          /* 背景 = 目的整层 */
383	  layers[0].data = (uint8_t *)dst_buf;
384	  layers[0].color_mode = EPIC_COLOR_RGB565;
385	  layers[0].width = (uint16_t)dst_w;
386	  layers[0].height = (uint16_t)dst_h;
387	  layers[0].x_offset = 0;
388	  layers[0].y_offset = 0;
389	  layers[0].total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
390	
391	  HAL_EPIC_LayerConfigInit(&layers[1]);          /* 前景 = 源整层 + 变换 */
392	  layers[1].data = (uint8_t *)src_buf;
393	  layers[1].color_mode = EPIC_COLOR_RGB565;
394	  layers[1].width = (uint16_t)src_w;
395	  layers[1].height = (uint16_t)src_h;
396	  layers[1].x_offset = (int16_t)(dst_cx - pivot_x);
397	  layers[1].y_offset = (int16_t)(dst_cy - pivot_y);
398	  layers[1].total_width = MYVENDOR_EPIC_PX_PER_ROW(src_stride);
399	  layers[1].transform_cfg.angle = (uint16_t)angle10;
400	  layers[1].transform_cfg.pivot_x = (int16_t)pivot_x;
401	  layers[1].transform_cfg.pivot_y = (int16_t)pivot_y;
402	  layers[1].transform_cfg.scale_x = EPIC_INPUT_SCALE_NONE;
403	  layers[1].transform_cfg.scale_y = EPIC_INPUT_SCALE_NONE;
404	
405	  memcpy(&out, &layers[0], sizeof(out));
406	
407	  ok = (lv_epic_blend(layers, 2, &out) == HAL_OK);
408	
409	  if (ok)
410	    {
411	      epic_invalidate_rect_rows(dst_buf, dst_stride, dst_w, dst_h);
412	    }
413	
414	  return ok;
415	}
